package com.hidewarnedattack;

import lombok.Getter;
import net.runelite.api.Skill;

enum AttackStyle
{
	ACCURATE("Accurate", Skill.ATTACK),
	AGGRESSIVE("Aggressive", Skill.STRENGTH),
	DEFENSIVE("Defensive", Skill.DEFENCE),
	CONTROLLED("Controlled", Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE),
	RANGING("Ranging", Skill.RANGED),
	LONGRANGE("Longrange", Skill.RANGED, Skill.DEFENCE),
	CASTING("Casting", Skill.MAGIC),
	DEFENSIVE_CASTING("Defensive Casting", Skill.MAGIC, Skill.DEFENCE),
	OTHER("Other");

	@Getter
	private final String name;
	@Getter
	private final Skill[] skills;

	AttackStyle(String name, Skill... skills)
	{
		this.name = name;
		this.skills = skills;
	}
}

package com.hidewarnedattack;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("hidewarnedattack")
public interface HideWarnedAttackConfig extends Config
{
	@ConfigItem(
			keyName = "hideNpcAttackOptionsDisplay",
			name = "Hidden Attack Display",
			description = "Displays a message when NPC Attack Options are being hidden."
	)

	default boolean hideNpcAttackOptionsDisplay()
	{
		return true;
	}
}

package com.hidewarnedattack;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;

import javax.inject.Inject;

import static net.runelite.api.MenuAction.RUNELITE_OVERLAY_CONFIG;
import static net.runelite.client.ui.overlay.OverlayManager.OPTION_CONFIGURE;

import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.TitleComponent;

class HideWarnedAttackOverlay extends OverlayPanel
{
	private final HideWarnedAttackPlugin plugin;
	private final HideWarnedAttackConfig config;

	@Inject
	HideWarnedAttackOverlay(HideWarnedAttackPlugin plugin, HideWarnedAttackConfig config)
	{
		super(plugin);
		setPosition(OverlayPosition.ABOVE_CHATBOX_RIGHT);
		this.plugin = plugin;
		this.config = config;
		addMenuEntry(RUNELITE_OVERLAY_CONFIG,OPTION_CONFIGURE,"Hide Warned Attacks overlay");
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.hideNpcAttackOptionsDisplay() || !plugin.isShowingOverlay())
		{
			return null;
		}

		panelComponent.getChildren().clear();

		panelComponent.getChildren().add(
				TitleComponent.builder()
						.text("NPC Attacks Hidden")
						.color(Color.RED)
						.build());

		panelComponent.setPreferredSize(new Dimension(
				graphics.getFontMetrics().stringWidth("NPC Attacks Hidden") + 10,
				0));

		return super.render(graphics);
	}
}

